(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,793789,e=>{"use strict";var i=e.i(843476),l=e.i(811337);function n(e){let n={li:"li",p:"p",strong:"strong",ul:"ul",...(0,l.useMDXComponents)(),...e.components},{AnketaCollapse:r,AnketaGroup:c,AnketaList:d,AnketaPoint:j,AnketaProse:x,MdxImage:h,Whisper:p}=n;return r||s("AnketaCollapse",!0),c||s("AnketaGroup",!0),d||s("AnketaList",!0),j||s("AnketaPoint",!0),x||s("AnketaProse",!0),h||s("MdxImage",!0),p||s("Whisper",!0),(0,i.jsxs)(c,{children:[(0,i.jsx)(r,{title:"Общая информация",defaultOpen:!0,children:(0,i.jsxs)(d,{children:[(0,i.jsxs)(j,{title:"Имя персонажа [русс|англ]",children:[(0,i.jsx)(n.p,{children:(0,i.jsx)(n.strong,{children:"Мо́ран | Moran"})}),(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"«Чёрный Рыцарь» — произошло оттого, что мужчина скрывает свою личность и обладает поистине достойными рыцарскими навыками (в средневековье так было принято называть рыцарей, скрывающих принадлежность к сеньору или истинную личность);"}),"\n",(0,i.jsx)(n.li,{children:"«Король сделок» — прозвище, привитое в эпизод развития чёрного рынка. По естественным причинам Моран всегда умел предложить то, от чего было затруднительно отказаться, когда к нему обращались;"}),"\n",(0,i.jsx)(n.li,{children:"Для более близких себе людей позволяет называть «Рэд» — такова его кличка ещё со времён преступного прошлого, своё прошлое и настоящее имя Моран умалчивает."}),"\n"]}),(0,i.jsx)(n.p,{children:(0,i.jsx)(n.strong,{children:"Каин О'Каннингем | Cain O'Cunningham"})}),(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"Настоящее имя Морана; вторая душа, которая жила с ним примерно половину из его возраста в Энкраже. Искупился 350 лет назад. В ходе биографии и истории он будет упоминаться лишь с точки зрения становления и появления Морана."}),"\n"]})]}),(0,i.jsx)(j,{title:"Возраст",children:(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"прожитый на земле: 35 лет."}),"\n",(0,i.jsx)(n.li,{children:"дата рождения — 01.04.1542г. | смерти — 08.05.1577г."}),"\n",(0,i.jsx)(n.li,{children:"прожитый в Загробном мире как грешная душа: 441 год"}),"\n"]})}),(0,i.jsx)(j,{title:"Пол",children:(0,i.jsx)(n.p,{children:"Мужской"})}),(0,i.jsxs)(j,{title:"Раса",children:[(0,i.jsx)(n.p,{children:"Химера."}),(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"Первое и самое главное для становления химерой у персонажа послужила очень сильная психологическая травма, способствующая получению ещё при жизни раздвоения личности. Данное раздвоение с каждым годом росло в более острый конфликт, из-за чего под момент прохождения в башне душа смогла окончательно разделиться на две составляющие части. Как оказалось по итогу, Каин стал проявлением львиной части химеры, символизирующей по всем канонам «добро», а Моран — проявлением змея, вездесущего «зла»;"}),"\n",(0,i.jsx)(n.li,{children:"Духовный тип Касар повлиял на душу таким образом, что Каин совершенно не знал о присутствии Морана и захвате собственного тела. Единственное, что он о себе знал, так это о частом желании спать и о хронической усталости, преследующей его уже не первый десяток лет. Всячески старался с этим бороться, но осознание присутствия и мысль о захвате «другой личностью» Каин вовсе не допускал;"}),"\n",(0,i.jsx)(n.li,{children:"Каин при жизни — это образ мечтательного юноши, желающего достигнуть столь высокого, столь благородного. Он в целом таил грёзы о более лучшей жизни, о более справедливом для себя начале, однако вынужден был подчиняться тем законам, которые у него есть."}),"\n"]})]})]})}),(0,i.jsxs)(r,{title:"Психологический профиль",children:[(0,i.jsx)(r,{title:"Характер",children:(0,i.jsxs)(x,{children:[(0,i.jsx)(n.p,{children:"С того момента, как Моран впервые зародился второй личностью в переломный момент жизни, будучи Каином, он стал существовать в состоянии фундаментального отрицания. Мир для него — не враг, но и не трагедия, а пустая конструкция, лишённая внутреннего смысла. В нём нет ни истины, ни баланса, ни точки опоры, за которую стоило бы держаться. Всё, что принято считать «порядком», он воспринимает как временную договорённость, обречённую на распад, и разрушение в подобной философии выступает исключительно логичным следствием наступления конца для чего бы то ни было."}),(0,i.jsx)(n.p,{children:"Моран не признаёт ни бога, ни морали, ни абстрактных ценностей; религия особенно вызывает в нём брезгливое презрение – как попытку придумать смысл там, где его никогда не было; иллюзия или же самообман, в которых людям лишь приятно утешаться, но не познавать грубую реальность. Чувства для Морана низменны, и значимость их ни в чём не измеряется; эмоции существуют, но не имеют веса. Речь идёт не об их отсутствии, а об ограниченности: Моран способен испытывать базовые эмоции — страх, раздражение, гнев, интерес, — однако сложные формы вроде сочувствия, любви или эмпатической привязанности ему недоступны. Между жизнью и смертью для него нет принципиальной разницы, как нет её между «правильно» и «неправильно», или же белым и чёрным. Все эти категории он считает бесполезными для принятия решений, но стоит держать в голове, что когнитивно Моран понимает эмоции других, просто не придаёт им должной ценности и не проецирует на себя – попытки вызова в нём какой-либо эмпатии могут вырвать из него разве что раздражение и скуку, а иногда – скрытую агрессию, если подобное сближение он расценивает как вторжение."}),(0,i.jsx)(n.p,{children:"Он не стремится доминировать и не нуждается в признании. Моран в том числе не спорит с чужими взглядами, но не из-за высокомерия, а из отсутствия интереса – как уже говорилось, чужое мнение для него не представляет ценности, так же как и сама идея соотнесения себя с кем-либо. Он действует исключительно признавая собственные цели и правила, а всё остальное уже — чужая территория, в которую он вмешивается лишь при наличии прямой выгоды, предпочитая сталкивать идиотов с новой реальностью, нежели пытаться их переубедить. Он не ненавидит людей как таковых — ненависть требует эмоционального вовлечения, — но и не видит в них самостоятельной ценности."}),(0,i.jsx)(n.p,{children:"Нигилизм стал частью самого Морана – он перестал искать смыслы, но и не страдает от их отсутствия. Он не чувствует пустоту как утрату — скорее это базовое состояние, в котором сострадание, любовь, привязанность в их общепринятом виде ему чужды. Возможны лишь функциональные формы привязанности, основанные на пользе, контроле и необходимости – всё, что он сохраняет рядом с собой, имеет чёткий перечень причин, по которым это должно существовать. Даже подобная привязанность, если так можно выразиться, не несёт в себе эмоциональной исключительности и легко подлежит пересмотру при изменении условий, и он может, проявляя терпение и расчётливость, всегда оборвать связь и найти замену неугодным."}),(0,i.jsx)(n.p,{children:"Моран всегда предпочитает размытым планам расписанные схемы, понятные условия и прогнозируемый исход. Взаимодействие с ним в целом всегда строится на выгоде: если хочется сделки — нужно оказаться полезным, иначе Моран даже не удостоит вниманием. Но даже если его интерес оказался зацеплен, для Морана он краткосрочен и легко заменим."}),(0,i.jsx)(n.p,{children:"Физическая боль или же психологическая, если мы говорим о пытках, не является для него сдерживающим фактором, а моральные давления не работают вовсе – терять ему совершенно нечего. Попытки задеть его прошлым, чувствами или уязвимостями не дают результата — он давно признал всё, что в нём есть, и не испытывает по этому поводу ни стыда, ни сожаления – совесть уже давненько была выкорчевана без остатка. В то же время, он способен применять всё вышеупомянутое в отношении жертв, если цель требует жестокости, не чураясь ни грязной работы, ни её последствий. В моменты сопротивления со стороны жертв может проявляться его маниакальный аспект: интерес к страху, злости, боли другого – подобные реакции ему понятны, они считываемы и потому занимательны, но данный интерес является вторичным и возникает как реакция на препятствие или сопротивление. Однако вне таких фаз Моран эмоционально нейтрален и предельно собран."}),(0,i.jsx)(n.p,{children:"Моран с лёгкостью врёт, уверенно и без внутреннего конфликта или же тревожных мыслей, не боясь ни последствий, ни возможной вины даже если смочь уличить его в чём-либо. Ложь для него выступает формой развлечения и способом управления; он умеет подстраивать её под собеседника, делая ту убедительной и логичной. Ему также свойственно использовать ложь не только ради выгоды, но и ради наблюдения за реакцией, проверяя степень доверчивости жертвы. И конечно же, зная о том, что так делает он сам, Моран внимательно относится к деталям и несостыковкам, потому обмануть его становится непросто."}),(0,i.jsx)(n.p,{children:"Моран никогда не стремился стать воплощением зла, но при этом для кого-то может преспокойно являться его воплощением, так как он – то, что каждый человек предпочитает держать на тормозах или же в кандалах. Он не бросает миру вызов сознательно — он просто не считает нужным подстраиваться под его (и чьи-либо ещё) ожидания."})]})}),(0,i.jsx)(r,{title:"Страхи",children:(0,i.jsxs)(d,{children:[(0,i.jsx)(j,{title:"Сотериофобия",children:(0,i.jsx)(n.p,{children:"Единственный и неповторимый страх Морана состоит в том, что он боится быть связанным с людьми какими-либо отношениями. Его начинает коробить, когда он чувствует привязанность людей к себе или их попытку сблизиться с ним через какие-то поступки или обязательства, навязывая свои личные отношения уровнем выше, чем простой выгодой. Моран не терпит к себе открытых привязанностей и «жертв», равно как и он не готов пожертвовать чем-то своим или же собой, если это не оправдано его целями и «рациональными» выводами."})}),(0,i.jsx)(j,{title:"Неофобия",children:(0,i.jsx)(n.p,{children:"Он боится измениться, боится подвергнуться чьему-то «влиянию» и смягчиться; боится увидеть в мире «какой-то смысл», тем самым, проявив слабость и привязавшись к чему-то. Моран считает, что привязанность делает человека слабым и позволяет контролировать даже самого дикого зверя."})}),(0,i.jsx)(j,{title:"Неизвестность",children:(0,i.jsx)(n.p,{children:"Моран чувствует некоторый дискомфорт, когда не может прийти к какой-то конкретной мысли или схеме действия — это сбивает его со стандартной схемы работы. Моран не любит сталкиваться с ситуациями, когда теряется в догадках даже он сам."})}),(0,i.jsx)(j,{title:"Страх зависимости, ограниченности",children:(0,i.jsx)(n.p,{children:"Ценит свободу больше собственной жизни, хотя и кажется готовым выполнить любое поручение."})}),(0,i.jsx)(j,{title:"Страх дать слабину",children:(0,i.jsx)(n.p,{children:"Стать слабым, немощным, неспособным дать отпор и противостоять кому/чему-либо. Уважает силу и верит в её необходимость для выживания."})})]})}),(0,i.jsx)(r,{title:"Мечты, цели",children:(0,i.jsxs)(x,{children:[(0,i.jsx)(n.p,{children:"Сложно сказать о мечтах Морана. Очень сложно. Его мечта всегда заключалась в том, чтобы мир был уничтожен, всё было мертво — мыслимое и немыслимое. Он мечтает об абсолютной пустоте, забвении, и только тогда его мятежный дух успокоится. Он не стремится самостоятельно воплотить мечту, но способствует тому, чтобы конец произошёл."}),(0,i.jsx)(n.p,{children:"На данный момент не имеет никаких чётких целей, кроме существования и сохранения собственной жизни. В случае Морана, цель приходит только с выгодой или острой необходимостью, руководствуясь ситуацией и подчиняясь своему собственному алгоритму. Одной из ведущих целей, в таком случае, можно отметить получение максимальной выгоды со стороны каждой сделки, ибо, в противном случае, смысла в сделке как таковой нет."})]})}),(0,i.jsx)(r,{title:"Биография (при жизни)",children:(0,i.jsxs)(x,{children:[(0,i.jsx)(n.p,{children:"Одним звучным днём, под звон похоронных колоколов, бич обратился в петлю, обмотанную вокруг шеи того, кто был рождён и выплеван в гнусный мир. Однако, мученику был дарован не покой, а маленькая миссия. Он молил об уничтожении, о покое и прощении, и именно в тот миг, в плясе танца смерти, появился проклятый, желающий отмщения, породившего зерно зла, возросшее в дерево."}),(0,i.jsx)(n.p,{children:"Ему никогда не хотелось жить. Он никого не просил об этом — и жизнь всё равно поступила иначе, отправив во мрак и приказывая подняться сквозь оковы боли и ненависти, ради того, чтобы стать тем, кем он есть. Наверное, что Каин, что Моран — оба никогда не забудут о прошлом. И если первый будет стремиться изменить прошлое будущим, то второй — уничтожит и прошлое, и будущее."}),(0,i.jsx)(n.p,{children:"Кто таков Каин? Душа, клеймённая мучеником. Каин родился на тот момент в раздробленной феодальной Германии XVI века, на западе, в Эльзасе, в её исторической на данный момент столице — Страсбурге. Вспоминая об этом периоде, всё, что можно сказать о нём — отвратительный этап. Несмотря на то, что ему повезло родиться в приличной семье того времени, богатство семьи которой сравнимо на нынешний лад с графскими имениями, где было много братьев и сестёр, по факту, никакой любви и её отголосков попросту не имело место быть в семьях того времени."}),(0,i.jsx)(n.p,{children:"Все аристократские дети были с сиделками, и Каин не стал исключением. В детстве он был довольно-таки тихим мальчиком, да и приходилось на него меньше всего времени отдавать одной из таких нянек, а вся причина была в том, что Каин являлся бастардом; плодом любви низкосортной служанки и на тот период князя. Пока мужчина был к матушке благосклонен, Каин мог находиться в семье и получать всё, что ему необходимо, но лишь формально, далеко от “высокого рода”, где ему не суждено и горсть в карман получить, как и быть признанным."}),(0,i.jsx)(n.p,{children:"В пики детских лет Каину то и дело приходилось сталкиваться с неравноправием: родители редко обращали на него должное внимание, а некоторые братья и сестры вовсе издевались, подслушав однажды из разговора отца, что он “бастард”. По этой причине Каину пришлось расти в большинстве своём в обществе рабочей прислуги, и даже родная мать не могла сказать ничего больше, кроме как того, что так они, хотя бы, не живут на улице. Так и рос Каин один, в своей маленькой комнатушке и с деревянной игрушкой, изредка встречая мать, и довольно-таки поздно: очень часто Каин просто не мог ждать и засыпал, а когда просыпался — её снова не было. Часто спорил со своими братьями и сёстрами, но это были детские заморочки, в которые взрослые вмешиваться по обстоятельствам не пытались."}),(0,i.jsx)(n.p,{children:"Как только мальчик достиг возраста семи лет, его отдали в монастырскую школу для получения образования, в то время как старших братьев предпочли отдать в епископальные. Именно в этом возрасте Каин начал уже психологически осознавать, что его в этой семье не то, что не любят… а прямо хотят, чтобы он пропал, исчез, ведь он — обуза. Совершенно ничего из себя не представляет. Сложно сказать, какой стресс мог испытывать ребёнок семи лет, осознавая, что он не нужен даже собственному отцу. В монастырской школе, ещё когда Каин учился писать, мальчик не раз составлял различные записи, которые вёл для того, чтобы не сойти с ума. Однако, возможностей было тоже не много, ведь из-за дороговизны бумаги и чернил, недоступных слугам, Каин мог писать только на тканевых рубашках, да и те не были разнообразны."}),(0,i.jsx)(n.p,{children:"На протяжении трёх лет Каина обучали грамматике, риторике, различной диалектике. С возрастом ему открылась арифметика, геометрия, астрономия и теория музыки. Из самого понравившегося можно отметить арифметику и геометрию. Также не упускал возможность читать книги, потому что она была доступна только при договорённости непосредственно с самим монахом. В возрасте 10 лет закончил монастырскую школу и, вероятно, не перевернись всё с ног на голову, стал бы монахом и принял аскетизм. Как-нибудь да выжил."}),(0,i.jsx)(n.p,{children:"Однако, чем дальше мальчик жил, тем тяжелее становилось. Каин окончательно ухудшил отношения с родственниками по их же капризу: стоило только однажды мальчику совершить “непростительную” (по мнению отца) ошибку, как он моментально был опущен до прислуги. А знаете, что за ошибка? Ошибка в танце. Каин тогда встретил много унижений в свою сторону, а вместе с ним получила и прислуга за то, что мало уделяла времени мальчишке и его умудрились запустить."}),(0,i.jsx)(n.p,{children:"Надежды стать лучшим и признанным канули в лету. Каин к 11 годам уже прекрасно понимал своё шаткое положение, не сомневаясь в том, что рано или поздно его выгонят из дома, никто не оказывал благосклонности, особенно официальная жена, поэтому необходимо было что-нибудь придумать. На мать полагаться было очень неудобно, ведь она работала буквально за троих (главная жена желала свести служанку в гроб), дабы Каин мог просто существовать и ни о чём не беспокоиться. Если их выгонят из дома, то полагаться на матушку тем более нельзя: она была уже немолода, слегка морщинистая и уже с больной спиной. По этой причине, обдумав всё, мальчик пришёл к самому вероятному, но труднореализуемому решению — воровство."}),(0,i.jsx)(n.p,{children:"Каин не особо был осведомлён о том, сколько может пригодиться на первое время, из-за чего принял решение взять столько, сколько получится. Он знал, что именно этот поступок станет тем “мотивом”, почему жалкого бастарда выкинут из дома, однако терпеть дальнейшее насилие в кругу семьи, оставляющее на его теле глубокие синяки, он был не в состоянии. Последовав зову своего разума, невзирая на инстинкты, Каин был вынужден пойти на риск: он осознавал, что хуже в его жизни уже ничего не сможет быть, если он не сможет выжить в этом жестоком мире. И начал воровать небольшие мешочки с гульденами. Однако наивный маленький Каин, обрадовавшись небольшой победе в миссии, ещё не знал, что у этого преступления был один единственный свидетель."}),(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"1 октября 1553 года."}),"\nㅤㅤㅤ"]}),(0,i.jsx)(p,{children:(0,i.jsx)(n.p,{children:"Это треклятое серебро… смотря на него, я вижу бездну алчности и боли, в которой утопаю; я вижу кровь, смешанную с землёй, и своё несчастное отражение. Я не жалею о том, что совершил великий грех, потому что это пойдёт на пользу… И не простит мне всевышний, и не простит мне душа, но я был вынужден. Иной мне жизни не сыскать. Я уверен, что никто не узнал, не заметил, ведь даже мелкие слуги воруют, вот, например, Мартиша, всегда что-то подворовывает с кухни... Почему же не могу и я? Конечно, не еду, но монеты, чтобы приобрести эту самую еду. А ведь если бы я мог, я хотел бы стать рыцарем..."})}),(0,i.jsx)(n.p,{children:"В то же время, Каин боялся гнева отца и возможности лишиться крыши над головой, а потому приходилось либо воровать у слуг, либо пытаться и вовсе вне дома. Мальчик довольно часто возвращался домой в синяках и различных ссадинах, но порой это своего стоило, когда в ладошках он приносил парочку гульденов с надеждой на хлеб. На ещё один чёртов день в его жизни. С каждым часом Каина всё больше начали привлекать к различной ответственности. С каждым годом этот “волосок” натягивался всё сильнее… к нему начали относиться как к прислуге в полной мере. Особенно в последнее время. Пока он был маленьким и делал ошибки, отец делал вид, что ничего не происходит, из-за чего у парнишки было в меру спокойное детство. Он даже игнорировал выходки, когда Каин умудрялся спорить со своими братьями. Единственное наказание, которому подвергался Каин (что, фактически, наказанием для него особо и не являлось) — изоляция в прислугах, где лицо виновника скрывалось в комнатах большого особняка в целях работы по дому."}),(0,i.jsx)(n.p,{children:"Всё, что происходило в промежуток подростковых годов, Каин помнит на самом деле отрывками: он не помнит причины, но помнит последствия. От небольших синяков до огромных гематом на теле, отеки, выбитые зубы, разбитые руки в крови. И женские крики, которые преследуют его сознание по сей день. Отцу начинало надоедать, что Каин постоянно пытается спорить, выкручивается из ситуации и язвит. Ему не нравилась его детская строптивость… мужчина отказывался принимать, что Каин начинает пытаться отвечать своим братьям и ставит их на место — эта грязь не имеет права не то, что на слово, но и на жизнь. Сам же Каин до сих пор не знает, почему перестал молчать. Вероятнее всего, главным толчком стало то, как “высокая семья” издевалась над матушкой. Вся прислуга и все члены семьи видели, как мачеха не давала покоя матушке и зачастую унижала её. А что же её дети? Брали пример, и не стеснялись такого свинского отношения. И хотя Каин не питал той искренней любви к матери, он был до ужаса ей благодарен за всё, что она делала, а потому не мог сидеть сложа руки."}),(0,i.jsx)(n.p,{children:(0,i.jsx)(n.strong,{children:"24 апреля 1554 года."})}),(0,i.jsx)(n.p,{children:"Эта… беспомощность, невозможность бороться, противостоять, терзала душу юнца, в то время как кулаки чесались сделать хоть что-то. Сумбурно мальчик перебирал различные мысли о том, как ему следует поступить, как бы он… поиздевался над этими выродками. Как бы отомстил… Вспышки различных идей накатывали неизведанной силой, яркой искрой, что Каин чуть не поддался соблазну их реализовать."}),(0,i.jsx)(p,{children:(0,i.jsx)(n.p,{children:"Когда я допустил одну единственную мысль об их возможной гибели… долгой, мучительной гибели, — моё лицо исказилось от ужаса: я осознал, что это… не я. Я не такой. Я не хочу убивать, мне следует просто оставаться послушным... Но они заслужили"})}),(0,i.jsx)(n.p,{children:(0,i.jsx)(n.strong,{children:"3 марта 1555 года."})}),(0,i.jsx)(n.p,{children:"Отец снова бьёт Каина. Что же в его арсенале? Посмотрим: кулаки… кнут. Ничего необычного. Это было самое типичное оружие, используемое монстром для того, чтобы в очередной раз поиздеваться над собственным отпрыском."}),(0,i.jsx)(p,{children:(0,i.jsx)(n.p,{children:"Вы знаете, что такое настоящее безумие? Безумие — это когда ты не принадлежишь самому себе; когда тебя топчут ногами и плюют в лицо; когда избивают и называют вещью. Мы были вещами; я был вещью своего «отца»: он неистово избивал меня на глазах у собственной матери, в то время как я не мог защитить её сердце. Жалкий и слабый. Мусор. Какой же я мусор… Почему я ничего не могу изменить? Я начинаю терять себя: каждый раз грежу о том, чтобы отомстить. Может, действительно стоит?..."})}),(0,i.jsx)(n.p,{children:"Но в сегодняшнем арсенале было что-то не то. В нём был… нож?"}),(0,i.jsx)(p,{children:(0,i.jsx)(n.p,{children:"Он ударил меня серебристым клинком, с него каплями капала кровь… Первое, что я почувствовал, была не боль, о нет, это был гнев. Настоящий гнев, кипящий во мне, будто в жерле вулкана. Пламя хотело вырваться… но я лишь прикусил губу, проскрипел зубами: я ничего не мог сделать. Тогда я впервые подарил миру своё горячее, озлобленное сердце. И проклял мир"})}),(0,i.jsx)(n.p,{children:"Его конечно же позже вылечили — отец не мог позволить так просто умереть своему «любимому» бастарду, который был извечной грушей для избиения. Но, кажется, все совсем забыли о психике Каина, которая начала трещать по швам после ощущения холодного металла у своего горла. В одном тёмном углу он ухмыльнулся этому ощущению, схватившись руками за горло — были ли это нервы или же что-то ещё?"}),(0,i.jsx)(n.p,{children:"На теле Каина до сих пор остались эти ножевые ранения, кои изуродовали его тело на всю оставшуюся жизнь, хоть они и смешались со шрамами иных событий. Впрочем, как оказалось, отец получал от этого неистовое удовольствие — настолько, что его нрав в некоторые моменты смягчался, но это было лишь до первой ошибки; до первого всплеска раздражения. Он был настоящим маньяком, наслаждаясь тем, как бастард пытается вырваться из его крепкой хватки и ответить. А его мать, связанная тугой верёвкой, очередной раз смотрела на то, как сына избивают. Глаза женщины были красными и опухшими: она каждый вечер плакала и молилась Богу о том, чтобы этот кошмар закончился. Казалось, в последнее время ей уже не было чем плакать…"}),(0,i.jsx)(n.p,{children:(0,i.jsx)(n.strong,{children:"14 апреля, 1555 год."})}),(0,i.jsx)(n.p,{children:"Очередной удар кулаком в лицо. В этот день Отец уж слишком сильно зарядил его по голове, и Каин будто… прозрел. Мужчина отпустил его с матерью и отправил в коморку, в то время как у Каина пошла кровь. Если бы в XVI веке знали, что такое сотрясение, то именно такой диагноз поставили бы Каннингему: в этот день его бросало то в жар, то в холод; шла кровь из носа, а те судороги он не позабудет даже в сущих кошмарах."}),(0,i.jsx)(n.p,{children:"Мальчик целую неделю был отречён от мира сего, лежал на кровати и думал… да ни о чём он не думал. По нему уже было видно, что он находится далеко не здесь, а где-то в прострации."}),(0,i.jsx)(n.p,{children:"Пришёл Каин в себя с довольно-таки большим трудом, когда он решил взять себя в руки и снова бороться за свою жизнь — и, мягко говоря, это действительно было для него большим психологическим шагом, ведь даже матушка не смогла на него повлиять так, как голос, который эхом пронзал его сознание и пытался донести одну единственную мысль — «Борись». После этой ситуации Каин более близок к реализации себя как Моран, и этот голос являлся именно его. Он сам... задавал своё будущее."}),(0,i.jsx)(n.p,{children:"С этого момента Моран заменил ему всех: он подговаривал его делать то, что не следует; рассказывал ему много нового, предполагал интересное и не оставлял в абсолютном одиночестве. Сказать, что Каин был рад — таки действительно, ведь у него всегда была мечта получить преданного и верного друга. Даже если это всего лишь игра его собственного воображения."}),(0,i.jsx)(h,{src:"/anketa-images/moran/moran-bio1.webp"}),(0,i.jsx)(p,{children:(0,i.jsx)(n.p,{children:"В этом мире ты станешь большим, чем ты был когда-то. Мы сделаем это. Я сделаю это"})}),(0,i.jsx)(n.p,{children:"За два года, набрав сумму, на которую можно однозначно выжить, Моран «убедил» Каина, что необходимо действовать, нельзя мириться со своим положением битьевой груши. Вопреки всем своим принципам… он действительно прислушался к Морану, очарованный его историей и предложениями, теми перспективами, которые ожидают его после совершения подобного. Ребёнок, что с него взять. Однако плюсы здесь были только для Морана…"}),(0,i.jsx)(n.p,{children:"К началу 1556 года, мальчик совершил покушение на жизнь своего отца. Это было похоже на настоящую бойню, в ходе которой Каину пришлось воспользоваться всеми своими силами и смекалкой для того, чтобы убить его. В удобный момент мальчик смог сбить его с ног, схватить нож и нанести несколько ножевых ранений, в ходе которого мужчина просто не выжил. Он пытался помешать мальчишке, однако матушка помогла заткнуть и задержать. До сих пор нельзя точно сказать, был это Каин или же его телом на этот момент завладел Моран. Сам же Каин, первый раз осознав, что пронзил плоть живого существа (он боялся сделать больно даже мухе, потому что на себе же испытал каково это быть грушей для битья), окончательно свихнулся, ступив на скользкую дорожку."}),(0,i.jsx)(p,{children:(0,i.jsx)(n.p,{children:"Почему… Я смотрю на свои руки и не чувствую ничего… лишь пустоту. Но, ведь, я впервые убил человека.... почему же я ощущаю… точнее, ничего не ощущаю? Я не хотел его убивать, не хотел…. Почему я это сделал? Я… да ты же заслужил. Чего я разнылся?"})}),(0,i.jsx)(n.p,{children:"Взгляд его тогда дрожал, а руки тряслись. Однако теперь уже Моран не собирался останавливаться на начатом: несмотря на уже мёртвое тело родного отца, мальчишка ещё несколько раз ударил по трупу ножом, вымещая накопившийся за столько лет гнев. И… это было настолько прекрасно, что вызывало дичайший азарт. Однако у Каина, конечно, только тихий ужас, ведь он не мог понять, почему его руки двигаются сами по себе. Хотя и не сказать, что мальчик не испытал облегчение, ведь было, на кого перекинуть вину; было, как воссоздать те крупицы баррикады сознания, чтобы остаться на берегу, а не нырнуть в пучины безумия."}),(0,i.jsx)(n.p,{children:"Как только Каин смог взять себя в руки, он с испугом выбросил нож и кинулся помогать матушке встать. Однако та, оставаясь в шоке, не сразу сообразила, что вообще происходит, ведь и сама действовала в моменте. Но им нужно было скрыться с места преступления как можно скорее через чёрный ход и выбросить одежду. Оружие. Почему-то Моран говорил об этом Каину, хотя и прекрасно понимал, что тот в состоянии аффекта вряд ли сможет даже пальцем пошевелить… в то же время, почему-то сам Каин снова прислушался, пусть страх и затмил его взор: он поставил чёткую для себя цель, что сегодня он хочет жить ради себя самого и ради любимой матушки."}),(0,i.jsx)(n.p,{children:'Всю энкражевскую жизнь Каин корил себя за смерть собственного отца: он ведь мог просто сбежать и оставить его в покое, но мятежный дух, живущий в сердце маленького ребёнка, не готов был мириться с безнаказанной несправедливостью. Впрочем, и у справедливости есть своя цена… Мачеха, узнав об этой вести, в первую очередь намеревалась найти убийцу и отомстить. Однако, к счастью, доказательств, указывающих на мальчика, у неё не было даже в лице слуг (когда отец избивал мальчика, то присутствовал только он сам и матушка). Кроме того, её тогда с детьми не было дома, а слуги просто занимались делами и "ничего не слышали". Даже больше: отец не считал необходимым говорить слугам о том, что он шёл “развлекаться”— просто шёл и развлекался. Так расследование, не успев начаться, и закончилось просто из-за отсутствия наличия каких-либо доказательств.'}),(0,i.jsx)(n.p,{children:"В то же время, когда мачеха и слуги узнали о смерти господина, сын и мать уже сбежали с деньгами. Честно признаться, даже матушка не была таким добрым человеком: невзирая на свои взгляды и принципы, она тоже жила не совсем честно и мечтала в последнее время о смерти мужчины, который избивал её и ребёнка. Даже насиловал… но всё равно это поразительно, насколько точно и легко это сделал Каин, когда даже она не могла решиться. Впрочем, матушка всё равно не винит его даже с тем, что он сделал."}),(0,i.jsx)(n.p,{children:"В первое время матушка боязливо относилась к своему сыну, пусть и верила, что он не виноват, однако закралась в ней мысль: в какого же монстра превратили её мальчика, что он решился нарушить закон Божий и совершить убийство? По большей степени, она и сама помогла, только вот Каин именно решился. И сделал. Однако любить она его от этого меньше не стала."}),(0,i.jsx)(n.p,{children:"Уехали они из Эльзаса в Лотарингию когда Каину было 14 лет, конкретно — в Пфальцбург (ныне Фальсбург). Благодаря состоянию, добытому сломанной психикой и кровью, они смогли переехать в другое место и жить спокойной жизнью. Однако и она долго не продлилась: несмотря на то, что у семьи было некоторое состояние, матушка и Каин в частности старались скрывать его от лишнего взора, дабы не нажить себе ещё больше проблем. Вопрос с жильём они закрыли на тот момент довольно-таки быстро: благо, как только они прибыли в Пфальцбург лишь в одних лохмотьях и с тяжелыми мешками, прогуливаясь по большому городу они столкнулись с одним добросердечным дядюшкой, который предложил приютить несчастную женщину с её маленьким сыном. Подозрительно, конечно, но выбор был невелик, хотя подозрения Каина развеялись, когда это оказался старый знакомый матери. У мужчины была своя таверна недалеко от центра города, и ему как раз не хватало рабочих рук в последнее время. И вот, удача, повернувшись лицом к Каину, была схвачена за хвост буквально: мальчик и матушка были поселены на верхних этажах таверны, в то время как сами оплачивали жильё работой в таверне — что может быть лучше?"}),(0,i.jsx)(n.p,{children:"Всё бы ничего, но известно, что в тавернах любило происходить, особенно во времена средневековья — пьяные драки и конфликты, которые приходилось разнимать. И Каин часто сталкивался с этим, но последние лет 5 всё укладывалось более-менее спокойно. Изменения начали происходить в 19 лет, когда юноша столкнулся уж с совсем обнаглевшими людьми. Мягко говоря, до него дошли слухи, что к ним в город прибыли рыцари. Они не часто приезжали в такой городок, но у гражданских был на них зуб, поэтому относились к ним крайне негативно: потеряв величие и статус, рыцари были вынуждены плавать в самой нише богатства, посему многие их представители часто решались на то, чтобы заняться различной контрабандой, грабежом купцов и так далее. Там, где они были, постоянно царила анархия, и сей ураган страстей не обошёл и Каина."}),(0,i.jsx)(n.p,{children:"Роковым моментом для Каина стала одна из таких бурь. Это был обычный 1561 год, совершенно не предвещающий беды. Даже наоборот, он в каком-то смысле был и вовсе счастливый: здесь Каин впервые познакомился с девушкой, которую дядя недавно взял в таверну, и её звали Адель. Она была из “свободной” от крипатства семьи, из-за чего была вынуждена пойти на работу, где и проработала вместе с Каином 3 года. За эти три года юноша впервые смог открыться другому человеку и познакомиться с ним куда ближе, чем у него выходило за всю свою жизнь. Сначала это знакомство было чересчур неуклюжим и даже нервным, однако со временем Каин научился принимать пылкий и чувственный нрав своей подруги, с которой постоянно проводил время в силу своей специфики работы. А конкретно сей год стал знаменателен именно потому, что Каин впервые смог признаться девушке в своих чувствах."}),(0,i.jsx)(n.p,{children:"Адель ответила взаимностью, и несколько месяцев у них был сладко-конфетный период, допустимый для тех времён, где они очень много уделяли друг другу времени и не обращали внимание на окружающий мир. Матушка и дядя заметили искру, родившую целый фейерверк между молодыми, однако их беспокоило, что они могут и вовсе забыться в этой суровой реальности. Особенно Каин, ведь он был чертовски мечтателен и хотел добиться многого. Всегда оставаясь наедине, он мог представлять только её мягкие на ощупь локоны, в которых хотелось зарываться с головой; её голубые сверкающие глаза, в которых он видел глубоководный океан жизни. К сожалению, влюбленная пара не спешила к совместной жизни в силу очень жестоких традиций, из-за чего долго не могла решиться на то, чтобы рассказать всё родителям и попросить согласие. По этой причине они решили поклясться друг другу в верности."}),(0,i.jsx)(n.p,{children:"Морана эта мечтательность мягко говоря начала раздражать. Конкретно за период этих трёх лет он довольно-таки сильно отдалился от сознания Каина и решил не вмешиваться — он знал, что произойдёт трагедия, которая позволит ему захватить тело даже без лишнего движения, и он был чертовски прав."}),(0,i.jsx)(n.p,{children:"Декабрь 1561 года. Обычный зимний рабочий день в таверне. Каин, матушка и Адель отстаивали свою ежедневную смену. Ближе к вечеру становилось прохладно и людно одновременно. Обстановка в целом оставалась мирной, пока на горизонте не появились рыцари, желающие прижать одного дядю за причинное место из-за долгов. Каин сразу увидев их понял, что дело запахло жареным. Как хорошо, что недавно они перепрятали сундук с деньгами, потому что эти шакалы только за ними и пришли. И для этого они не жалели ничего: ни людей, ни средств. Разведя конфликт за неуплату (сезон был бедный), рыцари развели конфликт на пустом месте, из-за чего затесалась огромная пьяная драка. Жертвами драки стали, как очевидно, матушка, Адель и дядя. Они ничего не могли противопоставить вооруженным рыцарям, которые начали в таверне вырезать всех без разбора, грабить. Мало у кого было оружия, способного противостоять вооруженным в доспехах людях. Время было не военное, и на границах Германии всё было более-менее спокойно под руководством феодала."}),(0,i.jsx)(n.p,{children:"На тот период Каин возвращался после одного дядиного поручения, а по возвращению смог увидеть только высоко выходящий дым, распространившийся на всю округу — поджог. Рыцари довольно обчистили всю таверну, перебили всех близких людей Каина, дабы показать, что неуплата карается жесточайшим образом. После столь открытого разбоя, к которому народ уже, к сожалению, привык, они принялись тушить здание, дабы не перешло на последующие стоящие. Когда он вернулся, то не смог найти в толпе людей даже после успокоения близких. Как он узнал от известных ему постояльцев, на их глазах убили всех, кто был причастен к этой таверне, потому что все были обязаны. Именно в это мгновение Каин потерял всё: себя, мир и свою личность. Он не знал, как жить дальше; он не знал, что делать дальше. Мир для него стал серым и пустым в одно око. Каин даже не плакал."}),(0,i.jsx)(p,{children:(0,i.jsx)(n.p,{children:"Почему же так больно?... Моё сердце и душу пронзили со всех сторон. В одно мгновение. Они кровоточат хуже любой раны. За что мне это, Господи, за что? Что же раб твой несчастный сделал неугодного тебе?..."})}),(0,i.jsx)(n.p,{children:"Он сломался. Мир растоптал его как игрушку, ещё несколько раз потоптался ногами и выбросил. Каин не хотел жить, у него не было даже смысла и какой-либо цели. Его мечты, идеи, любовь, семья — в одно мгновение. Несмотря на свой непоколебимый дух, казалось, он уже привык к потерям и ранам, но эту рваную боль не могло ничего спасти."}),(0,i.jsx)(n.p,{children:"И на сцену вышел Моран."}),(0,i.jsx)(n.p,{children:"Он помнил всё: боль, обиду, разочарование, отчаяние, страх и ненависть — помнил всё то, что сломало его мечтательного. И, несмотря на то, что змей с самого начала хотел заполучить тело, это не говорило о том, что он не исполнит желание Каина… Такое сладкое, такое манящее: «Убей, уничтожь этот мир. Отомсти и растопчи» — именно такие слова были выброшены в воздух целой мольбой отчаявшегося."}),(0,i.jsx)(n.p,{children:"Явление пустоты и горя заменило всю ту доброту и искренность — и сердце зачерствело. Ему не было смысла жалеть кого-либо или бояться. Он лишь хотел достичь большего и добиться справедливости, которой не заслуживали эти свиньи. По этой причине, первое, что пришлось сделать Морану в своём новом положении, — найти этих подонков. Парень не знал их имена или лиц, поэтому ему пришлось узнавать эту информацию от свидетелей. Благо, свидетелей было не только много, но и были конкретные факты. К примеру, он узнал, что группа из одного рыцаря и его приближенных не первый раз занимается подобным анархизмом, воруя у простого народа. Моран решил, что расправиться с рыцарем будет проще всего, но, конечно же, не в прямой стычке. Однако он станет первой целью — здесь уж никаких сомнений."}),(0,i.jsx)(n.p,{children:"Сняв недалеко жилье за те припрятанные деньги, Моран потратил несколько дней для удостоверения личностей — он не мог позволить себе совершить ошибку. Однако предпринимать пока что ничего не стал: ему необходимо нечто большее, чем просто убийство — ему нужна информация. По его делу пришлось совершить убийство пятерых человек, которые и устроили поджог. Морану пришлось потратить две недели для того, чтобы убить их всех: кого-то отравить, а кому-то перерезать глотку в тёмном переулке. Выйти на них было подобно переплёту верёвок, ибо у каждого хранилась та или иная информация на другого. Моран с интересом проникся в их интрижки, убирая одного за другими. Работа была чертовски неаккуратной из-за простой непривычки, неопытности, но учиться всё равно нужно. Моран был заинтересован в улучшении собственных навыков, поэтому не скупился тратить деньги на материалы и ресурсы — всё равно они были у него на “мушке”. Все трупы поочередно сбрасывались в недалекую речку, где предварительно Моран их ещё и обчистил. Примерно в этом возрасте, в свои законные 20 лет, у него начала появляться привычка забирать себе побрякушки и коллекционировать. Вы же не думаете, что у этого рыцаря друзья были из низкой касты? Это были разного рода торговцы, которые не так давно с большим интересом обдирали живущий итак худо-бедно народ."}),(0,i.jsx)(n.p,{children:"К одному из торговцев ему повезло попасть и в дом. Кажется, состояние у него было побольше, чем у тех, кого он чистил до этого, однако добыта эта прелесть была ещё страннее: в чужом доме Моран нашёл различную документацию “чёрных дел”, которые в наше время можно было бы назвать настоящей контрабандой. Любопытных товарищей он убил, оказывается. Впрочем, Морану до этого не было никакого дела — свою часть он выполнил."}),(0,i.jsx)(p,{children:(0,i.jsx)(n.p,{children:"Слушай, парень… как насчет игры? На кон я поставлю свою пустую жизнь. На какие условия играем? Давай-ка… начнём уничтожать. Начнём с малого: сначала это будут безобидные торговцы, потом рыцари, а где-то уже и бароны… как тебе идея? Или… ты хочешь, чтобы я вернулся и принялся за семью, которую ты так ненавидишь? Это дерьмо — я их убью одного за другим. Ну же, хочешь?"})}),(0,i.jsx)(n.p,{children:"Более Морана в этом городе не держало и можно было отдаться навстречу приключениям, в которых Моран много кем успел побыть. Путешествуя из одного города в другой, он изучал криминальные истории и высоких лиц этих мест, каких-то сомнительных личностей. Он знал, что такой бедняк без достойного образования мог податься только в монахов, но Моран и монах…. отвратительно. Поэтому он начал в одиночестве грабить, и начинал с малого. Благодаря своему небольшому путешествию, в ходе которого он совершал небольшие набеги для пополнения продовольствия, Моран вернулся в Эльзас. За это время он наловчился воровать, обчищал алкоголиков и тех, кто становился его жертвой. Нередко было возможным и проникнуть в чей-то дом, но подобное Моран совершал максимально редко: на его памяти он помнит только один такой удачливый заход через окно."}),(0,i.jsx)(n.p,{children:"Однако эти грабежи долго не продлились: по возвращению в Эльзас Моран временно прекратил преступную деятельность, когда пошли слухи: в последнее время многие деревенские и даже городские жаловались на странные убийства и различные грабежи. Это заинтересовало, ведь шайка использовала его же принцип грабежей и налётов (по крайней мере, как говорилось из слухов, а на тот период Моран и близко к Эльзасу не подходил), да и что-то часто стали происходить убийства. Вот, например, недавно прошёлся слушок по таверне, что убили одного жителями недалеко отсюда. А вот ещё один слушок, что нашли мертвую женщину, потом и ребенка. Интерес Морана только подогревался столь трепетной конкуренцией."}),(0,i.jsx)(n.p,{children:"Через некоторое время и он решил рискнуть и кого-то обчистить. Прошло тихо, на удивление, без происшествий. В подворотне ещё одно убийство пьянчуги, на этот раз с подозрением на связь с каким-то мутным типом. Не интересно. Не знающий чем себя занять Моран принялся узнавать, что произошло со старой семьёй. Узнавал исподтишка, поднимая очень далёкую тему и разговаривая местных пьянчуг. Так он и узнал, что его семья была смещена и разорилась."}),(0,i.jsx)(n.p,{children:"Убийства и кражи не заканчивались: Моран всё больше и больше пытался улучшить свои навыки, практикуясь порой и вовсе на простых людях, совсем уж без денег. Ночь была прекрасным временем, когда люди старались попасть домой после какой-нибудь пьянки или после позднего возвращения с работы, поэтому Моран старался вылавливать их одним за другим, забирая у них различные… побрякушки? Ладно, это и вовсе было мусором, но вдруг пригодится. Находил он жертв преимущественно на улице, хотя позже начал покушаться уже на таверных постояльцев, высматривая кого-то подостойнее — жить тоже на что-то нужно."}),(0,i.jsx)(n.p,{children:"Примерно так Моран и познакомился с парнем по имени Альберт, который работал в таверне. Это был весёлый паренёк. Постоянно забалтывал уши, рассказывая различные истории, делясь какими-то слушками. Да, это был один из немногих людей, с которым Моран вёл открытый и непринужденный диалог. Как-то раз Альберта чуть даже не ограбили ночью, однако Моран этому действию помешал, чем и заслужил доверие."}),(0,i.jsx)(n.p,{children:"Спустя несколько месяцев Моран встретил одного мужчину в таверне — и эта встреча тоже стала роковой в его жизни. Теперь о нём ходило уже немало слухов о том, что совершаются покушения и грабежи каким-то одиночкой. Парень всячески старался не попадаться и совершать покушения по ночам, ну а мелкие кражи мог и днём, из-за чего люди были напуганы. Таверна стала первым источником распространения слухов, как узнал от своего маленького товарища Моран. В этот же день он встретил человека, который, казалось, будет последним, на кого он сможет выйти. Они тогда были оба пьяны. Их познакомил Альберт, что в будущем станет большим удивлением для Морана, который полагал, что парень и вовсе никак не мог быть связан с… На удивление, тот пьянчуга не скромничал и рассказал ему, что он уже давно вместе с Альбертом наблюдает за Мораном и хочет предложить ему вступить в одну интересную банду. У неё огромные связи, и такой, как Моран, мог им быть полезен — его совершенно ничего не держало, цели ясны как день и у него был настоящий потенциал, который позволял расти к большему. Кроме того, он помогает в трудные ситуации и обладает нужными навыками. Такие надёжные люди ему однозначно нужны. Тогда этот мужчина представился Шумером. После разговора Моран действительно вступил. Шумер разделял лидерство банды с Питером Нирсом."}),(0,i.jsx)(n.p,{children:"Группировка их была пока что не самой большой, ведь она только начала набирать обороты, однако о ней всё чаще и чаще начинали ходить слухи в районах лесных и горных: банда занималась активным грабежом путников и торговцев прямо на дорогах южной Германии. Только в далёком будущем Моран поймёт, что связался не с простой бандой грабителей, но и настоящими убийцами и сектантами. И, чёрт возьми, это было самое прекрасное время в его жизни — он не жалел о том, что стал серийным убийцей, имея таких сумасшедших, но подаривших ему веру, товарищей."}),(0,i.jsx)(n.p,{children:"Его первой рабочей зоной оказался Эльзас, в котором на данном этапе работали Питер и Шумер. Что следовало делать? Ничего сверхъестественного: банда часто договаривалась разбивать лагерь в лесу и нападать на различных путников, купцов и даже на менял, которые считали себя самыми умными. На третьих нападать приходилось реже всего, потому что их часто охраняли на границах. Поэтому шайка занималась больше грабежами, чем убийствами, однако по возможности никто не хотел оставлять свидетелей преступления. Так, без фактических следов, под покровом тьмы банда из нескольких человек несла краденое в точку и распределяла согласно вкладу."}),(0,i.jsx)(n.p,{children:"Спустя несколько лет банда начинала расширяться: приходило всё больше людей, но не каждый из них задерживался надолго. И предателей приходилось Морану тоже убирать максимально оперативно — только хвоста не хватало. Преимущественно благодаря тому, что банда через некоторое время разделилась по различным городам, на расстоянии примерно двух-трех часов езды друг от друга. Ездили они в разные точки: Эльзас, Пфальцбург, Страсбург, Ландау, Кобленц, Кирхвайлер-на-Рейн... Основная точка деятельности конкретно Морана была и будет, конечно же, Страсбург, который он знал как свои пять пальцев. Вся южная Германия терроризировалась преступной бандой, которую не могли поймать практически 15 лет."}),(0,i.jsx)(n.p,{children:"Невзирая на однообразность работы, Моран не чувствовал от неё усталость — лишь возможность самореализоваться. Например, за это время он научился многому из криминального ремесла, занимался торговлей опиума. На тот период в Европе ещё не понимали опасность опиума помимо помешанности на нём как квинтэссенции, поэтому торговля проводилась без особых препятствий. Таким образом банда начала зарабатывать ещё больше денег, организовано объединяясь в рейды или разделяясь при необходимости по ключевым точкам. Иногда бывало и такое, когда приходилось залечь на дно, однако это не особо ударило по карманам членов организации. Вполне вероятно, что эта жизнь и стала ключом к созданию Мораном уже в Энкраже организованного чёрного рынка."}),(0,i.jsx)(n.p,{children:"Питер Нирс и Моран стали безумным тандемом своего времени: первый сильно повлиял на формирование извращённой психики второго, вытягивая клешнями последние границы, позволив родиться точке невозврата. Их знакомство — не случайность, а роковая конвергенция двух хищников. Нирс, уже легенда подполья, увидел в Моране не последователя, но зеркало собственной извращённой гениальности. Нирс посвятил Морана в ритуалы, где смерть становилась молитвой. Если Нирс вырезал сердца эмбрионов, то Моран, отвергая «банальность» убийств, начал коллекционировать органы жертв как артефакты, принося их в дар «Злу Всего Мира». Нирс учил, что мир — иллюзия, а истина кроется в боли. Для Морана это стало основой его нигилизма: «Если Бога нет, то Зло — единственный бог, достойный поклонения». У Нирса убийство было средством выживания и мистического обмена. Моран трансформировал это в перформанс отчаяния — его жертвы умирали медленно, их крики становились гимнами хаосу. Если Нирс поклонялся конкретным демонам, то Моран абсолютизировал само Зло как силу, не требующую имён. Его ритуалы — не мольбы, а плевки в лицо мирозданию: вырезанные органы, скармливаемые псам, символизировали отказ от всякого смысла. В то же время, если Нирс видел в страдании жертв диалог с адом, то Моран превратил боль в абстрактное искусство. Его пытки — не ради наслаждения, а чтобы услышать «звук ломающейся души» — единственную «музыку», достойную внимания. Их связь — не преемственность, а спираль деградации. Нирс хотел власти над миром; Моран стремился уничтожить саму идею мира, оставив лишь эхо своих жертв, плывущее по реке в вечность."}),(0,i.jsx)(n.p,{children:"Всеми описанными делами Моран занимался всю свою оставшуюся жизнь, все его последние 15 лет. Не переставал верить и, конечно же, делать всё по благо своих товарищей, к которым пусть и неосознанно, но всё-таки привязался. Например, Шумеру в своё время он действительно поклялся в том, что будет с бандой до самого конца, где символом стал амулет, с которым Моран до сих пор не расстается. Они убивали, грабили, продавали опиум, курили, пили и просто жили той «низкой» для всех жизнью, но, смею заметить, без каких-либо сожалений."}),(0,i.jsx)(n.p,{children:(0,i.jsx)(n.strong,{children:"Конец наступил 4 мая 1577 года."})}),(0,i.jsx)(n.p,{children:"Всё случилось в одно мгновение: кто-то из банды подставил Страсбург, четверо попались. И среди них был Моран, что искал лазейки к выходу, но потерял их среди сводов озлобленных служителей и палачей."}),(0,i.jsxs)(p,{children:[(0,i.jsx)(n.p,{children:"Сводчатый потолок, почерневший от копоти факелов, давил на плечи как грех, не смытый исповедью. Моран сидел на стуле с железными обручами — не пленник, а экспонат в музее чужой праведности. Перед ним, словно тени из средневекового скрипатория, выстроились трое: инквизитор в сутане, пахнущей ладаном и страхом; писарь с пергаментом, дрожащим в руках; палач, точащий нож о ремень."}),(0,i.jsx)(n.p,{children:"— Ты вырывал сердца человеческие, словно гнилые яблоки с древа познания. Признаешь ли?"}),(0,i.jsx)(n.p,{children:"— Да. И каждое — клал на чашу весов вашего бога. Знаете, что перевесило? Тишина."}),(0,i.jsx)(n.p,{children:"— Твой путь начался в Эльзасе, презренный! Позже ты перешёл в Страсбург, осквернил Лотарингию, Пфальцбург… И вот, демон, ты здесь — в доме Господнем!"}),(0,i.jsx)(n.p,{children:"— Дом? Не более, чем склеп, где ваши молитвы гниют вместе с крысами. А демоны… вас создали. Вы — их любимые куклы."}),(0,i.jsx)(n.p,{children:"— Sancta Maria, ora pro nobis…"}),(0,i.jsx)(n.p,{children:"— Скольких ты убил? Десять? Сто? Тысячу?"}),(0,i.jsx)(n.p,{children:"— Счёту нет. Но спросите своих князей — сколько жизней сжёг их «божественный» порядок? Вы сажаете на этот стул воинов, грабивших деревни? Нет. Вы целуете их руки. Так в чём моя вина, щенки божие? В том, что я не прячу трупы за хоругвями?"}),(0,i.jsx)(n.p,{children:"— Ты смеешь глумиться над Судом?!"}),(0,i.jsx)(n.p,{children:"— Ваш Суд — детская игра. Вы верите, что боль заставит меня ужаснуться? Я давно отдал свой ужас Злу, которое вы зовёте адом. Оно… благодарно."}),(0,i.jsx)(n.p,{children:"— Отрекись! Отрекись от дьявола, и душа твоя…"}),(0,i.jsx)(n.p,{children:"— Отреклись ли вы от своего дьявола? Того, что шепчет вам спалить деревню, если в ней нашли ведьму? Того, что оправдывает вашу алчность именем веры? Интересно — когда вы умрёте, он заберёт вас… или вы ему не нужны?\nㅤㅤㅤТишина становится пятой участницей диалога. Даже факелы трещат тише."}),(0,i.jsx)(n.p,{children:"— В протоколе запиши: «Одержим. Не раскаялся». Гори в геенне."}),(0,i.jsx)(n.p,{children:"— Не забудьте передать вашему богу. Он проиграл."})]}),(0,i.jsx)(n.p,{children:"Три дня. Семьдесят два часа. Четыре тысячи триста двадцать минут — именно столько времени понадобилось миру, чтобы перемолоть в своих жерновах последние крупицы человеческого в Моране. Подземелье, пропитанное запахом ржавых цепей и запекшейся крови, стало его алтарём. Его приковали к стулу так, будто хотели вбить в каменную плоть — железные оковы впивались в запястья, словно змеи, пьющие его волю. Каждый сустав хрустел, протестуя против нечеловеческой позы, но Моран не стонал. Он считал. Считал удары плетей, разрывающих кожу в клочья. Считал щелчки костей, ломаемых дробящим молотом. Считал капли крови, стекающие на пол в ритме макабрного метронома."}),(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"Первая пытка — ногти. Их вырывали щипцами, медленно, будто снимая перчатки с живой плоти. Он прикусил язык до металлического привкуса, но не издал звука. «Как в детстве», — мелькнуло в сознании. Тогда, под домашним арестом, над ним смеялись братья и сёстры, ломая мизинцы за украденный хлеб. Но сейчас — не боль пугала. Бесила их уверенность, что крики заставят его уверовать в их жалкого бога."}),"\n",(0,i.jsx)(n.li,{children:"Вторая пытка — пальцы. Перелом за переломом, фаланги превращались в осколки фарфора. «Молчишь?» — рычал палач, выворачивая кисть. Моран улыбнулся кровавой смазкой. Его дыхание стало глубже, медитативным — он учился дышать сквозь боль, как дышат сквозь огонь."}),"\n",(0,i.jsx)(n.li,{children:"Третья пытка — ноги. Дробильщик с хрустом раздробил колени. Тело дернулось в конвульсиях, но разум уже плыл над — наблюдал со стороны, как окровавленная плоть корчится в цепях. «Интересно, они знают, что ломают труп?» — подумал он, ловя взгляд своего отражения в луже. Глаза, горящие адовым углем в мертвенно-бледном лице, казались чужими."}),"\n",(0,i.jsx)(n.li,{children:"Религия. Это слово теперь вызывало у него спазмы смеха. Они молились, эти твари, перед тем как резать его. Целовали крест, шептали псалмы, а потом — рвали ногти, словно это жертва во имя их гниющего неба. «Ваш бог — трус», — хотелось крикнуть им. «Он прячется, пока вы делаете его грязную работу». Но Моран молчал. Молчание стало его молитвой."}),"\n",(0,i.jsx)(n.li,{children:"Тишина. Она обволакивала его в перерывах между пытками, густая, как смола. В ней он слышал голоса: шепот матери, которую забивали камнями за её жалкий статус и смелость; хрип товарища, захлебнувшегося собственной кровью в канаве; смех любимой, ставшей пеплом на костре горделивых клинков. «Все они здесь», — понял он. Мёртвые держали его на этом стуле, не давая потерять сознание."}),"\n",(0,i.jsx)(n.li,{children:"Сепсис. Заражение крови началось с незаметной царапины — и поползло по венам, как огненная лоза. Теперь галлюцинации стали реальнее палачей. Стены плавились, превращаясь в лица тех, кого он предал. Тени шептали: «Ты наш последний грех. Наше чистилище». В бреду он видел Питера Нирса — тот сидел в углу, обгладывая кость, и смеялся: «Ты хотел стать Злом? Теперь ты — его испражнение»."}),"\n",(0,i.jsx)(n.li,{children:"Последние минуты. Веки налились свинцом, но он заставил их оставаться открытыми. В тусклом свете факела кровь на полу складывалась в узоры — карту мира, который он ненавидел. «Смотрите», — прохрипел он в пустоту. «Ваше добро — это яма с гниющими трупами. Ваша вера — пепел, развеянный над могилами детей. А ваше Зло…»"}),"\n"]}),(0,i.jsx)(n.p,{children:"Он не договорил. Смерть пришла не как избавительница, а как старый знакомый — положила костлявую руку на лоб и выключила свет."}),(0,i.jsx)(p,{children:(0,i.jsx)(n.p,{children:"Пусть Зло Всего Мира выжжет это лживое небо. Пусть реки станут кровью, города — кострами, а их боги… пусть они съедят друг друга"})}),(0,i.jsx)(n.p,{children:"На полу осталось лишь тело — искорёженное, но с улыбкой. И усталыми глазами."}),(0,i.jsx)(n.p,{children:(0,i.jsx)(n.strong,{children:"13:34. 8 мая, 1577."})}),(0,i.jsx)(n.p,{children:"Прощай, мир."}),(0,i.jsx)(h,{src:"/anketa-images/moran/moran-bio2.webp"})]})}),(0,i.jsx)(r,{title:"Жизнь в Энкраже",children:(0,i.jsxs)(x,{children:[(0,i.jsx)(p,{children:(0,i.jsx)(n.p,{children:"Ему показалось, что он раздвоился, раскололся пополам, и одна его половина была горячей как огонь, а другая холодной как лед, одна была нежной, другая — жестокой, одна — трепетной, другая — твердой как камень. И каждая половина его раздвоившегося «я» старалась уничтожить другую"})}),(0,i.jsx)(n.p,{children:"Каин и Моран стали одним целым, но с разными сторонами одной монеты: Каин стал добрым и горделивым львом, что благородно себя несёт и живёт, а Моран — жестокосердным змеем, желающим всё поглотить и уничтожить. Они стали полными противоположностями, жизнь которых поначалу зависела друг от друга."}),(0,i.jsx)(n.p,{children:"Каин никогда не знал о существовании своего раздвоения личности и не подозревал даже после того, как совершил искупление. Лев стал первым, кто оказался на поверхности за первые сто лет, просто потому что хотел жить, в отличие от Морана. Башню проходил Каин, поэтому Моран полноценно в этом не участвовал. Благодаря тому, что он существовал как паразит, очень многое Моран узнавал без лишнего вмешательства, что, несомненно, очень помогло ему разобраться в загробной жизни и её правилах, не появляясь практически на свет и продумывая нечто новое."}),(0,i.jsx)(n.p,{children:"Ему всегда приходилось чередовать управление телом с Каином, заставляя его насильно засыпать, дабы получить контроль. Первое время ему с трудом это давалось, но со временем Моран научился обходить Каина, и всё чаще и чаще заставлял его спать, вдавливая его душу в пустоту. Если бы Каин не сбежал рано, то Моран мог бы и вовсе такую личность и её историю уничтожить. Однако не повезло."}),(0,i.jsx)(n.p,{children:"Жизнь Морана в Энкраже первое время была довольно-таки скудной: ему предстояло многое узнать, не вызывая трудности ни себе, ни Каину, и научиться брать тело под контроль. Как только это стало возможным спустя пару лет, он начал развивать способности на арене — долго, упорно и периодически, как позволяла возможность захвата тела. В одиночестве он укреплял свой дух и тело, что в будущем сыграет немаловажную роль в становлении змея таким, каким он есть сейчас. Он старался не наживать никаких проблем и следовать правилам, хотя это было совершенно не в его характере. По крайней мере, до тех пор, пока Моран не узнал о “палаче”, “вершителе” и тёмной ипостаси. Как думаете, фанатичного от Зла Всего Мира змея это заинтересовало? Даже очень."}),(0,i.jsx)(n.p,{children:"Не успело ему тогда исполниться даже 60 лет, как Моран уже начал по мере возможности пытаться привлечь к себе внимание Сталкера. Он не был уверен в теории того, что сможет избежать наказания, но стремления встретиться с легендарной личностью были куда выше того, чтобы бояться каких-то сверхъестественных пыток. В какой-то степени это даже вызывало дополнительный интерес, поэтому Моран решил начать с самого любимого: анархия и вандализм. Сталкер не заставил себя ждать уже со второй попытки, из-за чего мужчина решил проверить одну интересную теорию с паразитированием душ химеры. Удивительно, однако пока Каин существовал как основная душа, Моран мог скрываться за ним и избегать наказаний Сталкера. Конечно, как только мужчина выходил наружу, то погоня возобновлялась, однако это уже было не столько проблемой для змея, который скрывается столько, сколько себя вообще помнит. Лишь спустя два года Моран попался с поличным под наказание, но тут скорее сыграл тот фактор, что он и сам стремился уже наконец-то понять, кто же такой Сталкер. Увидеть в лицо, раскусить сущность и идеи."}),(0,i.jsx)(n.p,{children:"Каково было разочарование Морана, когда после первого раза он понял, что попросту ничего не помнит, а на его теле остались лишь продолжительные раны, которые в дальнейшем стали шрамами. Он на такое не подписывался: любые попытки вспомнить приносили ему только головную боль, из-за чего Моран начинал только сильнее злиться. Знал бы он, что происходит всё так, то ни в жизни не дал бы себя поймать. По этой причине Моран временно перестал провоцировать Сталкера, продумывая более лучший план для реализации своих идей."}),(0,i.jsx)(n.p,{children:"В возрасте 60 лет пребывания в Энкраже Моран познакомился с Раймоном Диасом, который в будущем станет ему не только близким товарищем, но и отличным союзником. Знакомство произошло, кстати, не на арене, а в библиотеке, когда они оба интересовались информацией, связанной с пустыми. Поначалу они относились друг к другу с большим недоверием, однако всё чаще жизнь начинала их сталкивать вместе: арена, гостиная, различные задания и попытки хоть как-то выбраться из замка и получить больше информации. По этой причине Раймон решил предложить Морану временное сотрудничество, в ходе которого оба получали одну единственную выгоду — информация. У змея не было причин отказывать. Позже они узнали, что у них очень много общего, а когда Моран рассказал о своём отношении и планах (он этого ничуть не стеснялся, да и бояться ему было нечего), Раймон яро загорелся помочь в их реализации. Так и началась дружба змея и лиса, что пережила вековые испытания и доказала, что они преданы друг другу и следуют единственной цели — достижению Зла Всего Мира, и, соответственно, уничтожения мира."}),(0,i.jsx)(n.p,{children:"Здесь же Моран знакомится с сестрой Раймона — Эридой, что ходила за ним хвостиком. Сначала он не сильно обращал на ногицунэ внимание, однако по мере её роста сил и вкладу их отношения улучшились."}),(0,i.jsx)(n.p,{children:"Стоит только Каину искупиться в свой 91 год, как Моран сразу чувствует долгожданную свободу и необходимость действовать так, как изначально и было задумано. В первую очередь Моран решает разобраться с вопросом о том, каким образом он сможет обезопасить свои выходы за территорию замка и даже за бастионы. Моран договорился с Хранителем о том, чтобы получить артефакт взамен на несколько услуг, благодаря чему через пару месяцев путешествий за горы Энкража он таки смог добиться того, чтобы найти необходимый ресурс и Хранитель выковал ему легендарное оружие “Номад”. Это путешествие выдалось одним из самых интересных на опыте Морана. Теперь, имея оружие и возможность противостоять любой трудности, ответственность и идеи возросли. Причём, настолько, что Моран наконец-то решил снова заняться Сталкером, ибо прошлый опыт ему уж никак не понравился. В его интересах было запомнить хоть что-то и понять, то ли это верховное существо, которое ему необходимо. Пусть пройдёт хоть двадцать лет или несколько веков, но Моран никогда не откажется от своей идеологии. Даже больше: он сделает всё, чтобы получить в свои руки последователей, как и случилось с Раймоном Диасом."}),(0,i.jsx)(n.p,{children:"В возрасте 91 года также начинается официальная карьера наёмника."}),(0,i.jsx)(n.p,{children:"Моран продолжает скрываться от Сталкера, однако он не мог спокойно прятаться в своем укрытии, сидя сложа руки. По этой причине змей начинает медленно выходить и встречаться с грешниками для выполнения каких-то задач в целях выгоды. Нередко за ним был замечен и просто выход за территории бастионов, где Моран занимался различными поисками каких-то артефактов и ресурсов. Насколько помнится, даже сейчас всё его логово поголовно забито различным сырьём и драгоценностями, которые можно использовать в своих нуждах. По причине того, что со Сталкером лучше в замке действительно было не пересекаться, мужчина всячески стремился пополнить свои запасы и даже изучить пару вещей вне этих территорий. Кроме того, дабы более смягчить свою кару, он продолжает сотрудничать с Хранителем, но теперь не только за артефакт, но и для уменьшения шанса получить наказание. По этой причине Хранитель решает его приставить патрульным к западному бастиону, который он и ныне часто проведывает для уточнения обстановки и регуляции пустых."}),(0,i.jsx)(n.p,{children:"Второй раз змей попал к Сталкеру уже осознанно, ему тогда было 95 лет. Снова были выбраны избиения с психологическими пытками. И второе, кажется, стало последним основополагающим компонентом для того, чтобы мужчина забил себе в память лишь одну вещь — это не Зло Всего Мира. Ему не нужно было помнить всё, а лишь прийти к одному факту в процессе издевательств: Сталкер был лишь палачом, что наказывал за совершение преступлений в ходе всей жизни здесь. Нет. Морану нужно было идти ещё глубже… не здесь его заветное Зло. После того, как Моран сделал окончательный вывод, он решил более не интересоваться Сталкером и оставил свою деятельность вновь в покое. Но до поры до времени, конечно: периодически ему приходилось прибегать к насилию во многих формах для конкретных ситуаций. Метки появлялись по всей его правой руке и всегда горели чёрным цветом, неприятно обжигая, однако они не доставляют особого дискомфорта змею."}),(0,i.jsx)(n.p,{children:"Вопрос был лишь в погонях, и, кажется, научиться бегать от Сталкера — это настоящее искусство, ведь он практически вездесущ. В этот же период он открывает у себя способности Каина, но не практикует их."}),(0,i.jsx)(n.p,{children:"К 1700-му, когда Морану исполняется 123 года, «чёрный рынок», как организация, набирает наибольшее количество сторонников."}),(0,i.jsx)(n.p,{children:"Быть наёмником, а позже заняться и дютанством в свои 172 года, забирая у людей грехи, — смелое решение. Как минимум потому, что Морана Сталкер всё же подловил в замке и чуть не забрал его душу. Невзирая на то, как он помогал Энкражу от пустых, это не покрывало его вины за все остальные преступления. Однако здесь Моран находит способ, как обходить наказания Сталкера. С новыми знаниями он возвращается к сторонникам и начинает реорганизацию рынка таким образом, как мы знаем его сейчас."}),(0,i.jsx)(n.p,{children:'К 1750 году Моран находит интересный артефакт "Меч Созидания и Разрушения", благодаря которому он воссоздаёт особенности бара "Чёрный змей", что ныне считается сердцем всех трёх организаций. Начинается популяризация услуг чёрного рынка и поиска всех заинтересованных и по сегодняшний день, и эта небольшая история, перевернувшая политику взглядов грешного общества, позволила рынку раскрыть весь потенциал и привлекать на сегодняшний день как можно больше к себе внимания. Главной причиной подобного на данный момент становится то, что всё сложнее и сложнее получать предметы легальным путём, а изучать мир становится всё опаснее, что активизирует работу всех трёх организаций и расширяет её аудиторию.'}),(0,i.jsx)(n.p,{children:"На трехсотлетие змея происходит знакомство с “только переродившейся” Эстер Клеман, что решилась пойти на арену и опробовать свои возможности. Моран в таком возрасте уже редко заходил на арену, ибо пик его сил был достигнут в более ранние года благодаря частым тренировкам и в будущем уже небезопасному наёмничеству. Однако в тот момент он зашёл уж слишком удачно и действительно сразился с новенькой. Сражением это, конечно, назвать было довольно трудно, ведь Моран практически ничего и не делал. Нет, если быть точнее, то внимательно наблюдал и выявлял потенциал, который сразу же заметил за девушкой. Именно он стал той персоной, что впервые порекомендовал девушке взять в руки лук и стрелы, а не пробовать с холодным оружием — это действительно не её стиль боя. Он не сразу решается взять девушку к себе в ученицы, но для него это было нечто новым и, возможно, даже выгодно-полезным. Попробовать? Моран предварительно поинтересовался мнением своего друга — Раймона. Тот сказал, что если ему интересно возиться с лишним грузом при его работе, то может попробовать. Так и быть."}),(0,i.jsx)(n.p,{children:"Несмотря на свою занятость, первое время Моран уделял довольно-таки много времени своей подопечной и даже умудрялся её брать на выходы. Да, она была тяжелой ношей, но благодаря смекалке девчуля не отставала, да и смышленой она была — быстро всё схватывала. Можно сказать, что Моран был где-то глубоко в душе и доволен, что не потратил своё время зря."}),(0,i.jsx)(n.p,{children:"Однако не всему Моран мог научить лисицу, и здесь ей необходим был уже магический наставник, ибо лисы однозначно лучше найдут язык, нежели он. По этой причине, с горем да пополам, Моран смог добиться заветного “посмотрим” от Раймона, который, как было известно, относился к женщинам с некоторой нелюбовью."}),(0,i.jsx)(n.p,{children:"Через сорок лет к их компании присоединяется не менее наглая и настойчивая личность, имя которой — Солер фон Клейст. На удивление, парень только недавно родился, но уже кое-что умел. За пылкий нрав и необычные способности (в том числе и магические) Моран решил, что и его можно взять под крыло и сделать надёжным союзником, как и случилось. Так вышло, что тренировались они группой, но Моран, всё же, отдавал большее предпочтение именно допплеру, так как основная его сила была в физических навыках и особенно фехтовании, чем они постоянно и занимались."}),(0,i.jsx)(n.p,{children:"Случались и ситуации, когда Эстер и Солер сильно спорили или даже ругались, однако это скорее было похоже на сопернический дух, нежели капризы, поэтому Моран и Раймон не особо стремились их сдерживать. Нередко, кстати, они заставляли их тренироваться друг против друга, ведь они были настоящими противоположностями по профилям — и у каждого в противоположных профилях были большие слабости."}),(0,i.jsx)(n.p,{children:"С тех пор прошло много времени, однако компания продолжает поддерживать отличные отношения. Теперь их ученики не дети, однако Моран всё равно не скупится дать им совет или другой в той или иной ситуации, но, конечно, не настаивает — пора бы пожить и своей жизнью."}),(0,i.jsx)(n.p,{children:"До сих пор Моран не отказался от своей основной деятельности и продолжает заниматься тем, с чего начинал. Если быть точным, то теперь он является одним из востребованных поставщиков каких-либо ресурсов довольно-таки у многих личностей. Кроме того, для хороших знакомых при наличии ключей он начал заниматься поставкой алкоголя и наркотиков. Сам же чертовски подсел на сигареты за последние сто лет. Завёл неплохое рендеву с Эридой Диас, которому проявляет свойственный азарт. Ведёт чёрный рынок по линии развития. Ну и, конечно, теперь ему ещё интереснее заниматься дютанством, забирая чужие грехи и воспоминания, которые хранит до лучших годов, ведь ему ничего более не мешает. Разве что жгущая извечно рука, но всё это ничто."}),(0,i.jsx)(n.p,{children:(0,i.jsx)(n.strong,{children:"Ведь его цель заключается в нахождении Зла Всего Мира, и то, что он переживает сейчас, никчемная мелочь по сравнению с тем, что даст ему это Зло."})})]})})]}),(0,i.jsxs)(r,{title:"Дополнительно",children:[(0,i.jsx)(r,{title:"Факты о персонаже",children:(0,i.jsxs)(d,{children:[(0,i.jsx)(j,{title:"Личные предпочтения",children:(0,i.jsx)(n.p,{children:"Невзирая на тот факт, что Моран является гетеросексуалом, по большей степени, он не испытывает нужду в романтике или же сексе, вступая в половой контакт по большей мере по договорам или «когда сойдутся звёзды», т.е. будет настроение."})}),(0,i.jsx)(j,{title:"Самоидентификация",children:(0,i.jsx)(n.p,{children:"На данный момент известно, что Эльзас относится к северо-восточным землям Франции, однако, несмотря на это, Моран продолжает относить себя к германцам. Хотя, в то же время, лично Моран не поскупился выучить французский язык для демонстрации своей образованности."})}),(0,i.jsx)(j,{title:"Сотериофобия",children:(0,i.jsx)(n.p,{children:"Религиозная тема — всё, что связано с религией, откровенно корёжит Морана. Он реагирует на это в принципе как демон, которому показали крест. Моран испытывает отрицание и отвращение к религии, что демонстрирует очень не характерное ему резкое поведение: раздражительность, закрытость, неестественную саркастичность и язвительность. Несмотря на свою потенциальную нелюбовь и ненависть к религии, Моран очень хорошо осведомлён о её основах и принципах в силу того, как инквизиция навязывала христианство, ну и из-за того, что учился на монаха в детстве. Он наизусть знает многие работы."})}),(0,i.jsx)(j,{title:"Статистика",children:(0,i.jsx)(n.p,{children:"За всю свою жизнь Моран умудрился убить около трёхсот людей."})}),(0,i.jsx)(j,{title:"Профессиональный статус",children:(0,i.jsx)(n.p,{children:"В Энкраже все осведомлены о том, что мужчина никогда не занимается чем-либо без выгоды. Кроме того, он не торгуется и всегда знает цену за свою работу. Всегда выполняет заказы, и может взять совершенно любой заказ за соответствующую цену. За последние лет 300 известен как один из грешников-наёмников, способных выполнить самую опасную и грязную работу."})}),(0,i.jsx)(j,{title:"Истинная природа",children:(0,i.jsx)(n.p,{children:"Фактически, никто не знает о том, что Моран является химерой: он никогда не умел превращаться в полноценное существо, ибо эта способность подвластна только Каину. По этой причине, все те, кто знаком с Мораном, часто любят считать вуивром, которым он не является."})}),(0,i.jsx)(j,{title:"Ученичество",children:(0,i.jsx)(n.p,{children:"Эстер Клеман была первой ученицей, которую он встретил на арене и провёл с ней несколько дуэлей. Позже Моран заинтересовался девушкой, видя в ней перспективы, посему занялся её обучением. Не грех будет сказать, что это именно он посоветовал ей взяться за лук, однако по стечении обстоятельств, был вынужден отдать на попечительство Раймону Диасу. Вторым учеником, буквально через десятку лет, стал Солер фон Клейст."})}),(0,i.jsx)(j,{title:"Деятельность",children:(0,i.jsx)(n.p,{children:"Работает Дютаном, то есть отмывает чужие грехи за хорошую награду. Но, если быть совсем честным, Моран попросту копит эти грехи для эксперимента. При наличии свободных ключей занимается контрабандой наркотиков и алкоголя дополнительно, обеспечивая бар или же тех, кто напрямую запросит."})}),(0,i.jsx)(j,{title:"Привычки",children:(0,i.jsx)(n.p,{children:"Имеет очень острую привычку курить: в любую свободную минутку возьмёт сигарету. Подметив это, Эрида даже подарила ему зажигалку. И когда Моран особенно зол, довольно часто он щёлкает крышкой этой зажигалки, прислушиваясь к звону. Также любит пить, но только за компанию."})}),(0,i.jsx)(j,{title:"Наказания",children:(0,i.jsx)(n.p,{children:"Моран не раз попадал под наказания Сталкера, из-за чего уже не питает к нему никакого интереса. У змея огромное количество шрамов на теле из-за насильственных наказаний со стороны Сталкера. Как итог, змей вообще не испытывал при этом ничего, как и сейчас не испытывает. Помнит и отголоски психологических издевательств, но Моран остался непробиваем."})}),(0,i.jsx)(j,{title:"Арена",children:(0,i.jsx)(n.p,{children:"Частый посетитель арены. Первые двести лет его там можно было встретить прямо на тренировках, однако сейчас Моран просто наблюдает за новичками и их способностями."})}),(0,i.jsx)(j,{title:"Манера общения",children:(0,i.jsx)(n.p,{children:"В некоторых ситуациях при разговоре с девушками имеет свойство называть их английским «Wifey», обращаясь с некоторой долей издёвки, что можно читать в его интерпретации как «Котёнок», возможно «Лапочка»."})})]})}),(0,i.jsxs)(r,{title:"Внешность",children:[(0,i.jsxs)(x,{children:[(0,i.jsx)(n.p,{children:"На первый взгляд во внешности Морана нет ничего, что сразу выдало бы в нём нечто неестественное, что кричало бы во всеуслышание – вот оно, ходячее зло, желающее уничтожить мир! Моран выглядит аккуратно, сдержанно и даже располагающе — ровно настолько, чтобы не привлекать к себе лишнего внимания. Даже стоя рядом, он никогда не давит своим присутствием, но проявляется весьма постепенно, по мере наблюдения, когда взгляд начинает цепляться за детали, не складывающиеся в привычную картинку человеческого, которого ожидаешь при знакомстве."}),(0,i.jsx)(n.p,{children:"Лицо Морана симметрично и холодно, лишено подвижности и яркости. Кожа бледная, без румянца или признаков усталости — создаётся ощущение мертвенной плоти, застывшей в выразительной ясности, но никак не в экзистенциальном ужасе перед смертью. Черты вытянутые: узкое лицо, подчёркнутая линия скул, орлиный нос с едва заметным изгибом на кончике. Его мимика крайне скупа: чаще всего лицо сохраняет нейтральное, отстранённое выражение; редкая ухмылка выглядит скорее как рефлекс, лишённый тепла, нежели полноценная эмоция в ответ на источник."}),(0,i.jsx)(n.p,{children:"Особое внимание привлекают его глаза – их радужка имеет выраженный, лимонно-янтарный оттенок, неестественный для человека, скорее уж для змеи, а зрачок — точечный, с заметным внутренним кольцом, создающим ощущение двойственности взгляда. Взгляд не выражает эмоций, но производят эффект постоянного наблюдения, будто Моран постоянно находится в состоянии оценки, и если бы он был более критичный или же наглый, то озвучивал бы каждый найденный недостаток. Однако молчание под долгим зрительным контактом вызывает дискомфорт: взгляд кажется слишком сосредоточенным и внимательным, словно он выискивает слабые места и проводит допрос, нежели ведёт какой-нибудь поверхностный диалог."}),(0,i.jsx)(n.p,{children:"Внешние изменения глаз и волос напрямую связаны с использованием магии: в обычном состоянии волосы Морана тёмные, почти смоляные, густые, с прямой длинной чёлкой, частично закрывающей лоб и линию бровей. Иногда он зачёсывает волосы назад, приподнимая левую прядь, в то время как остальная часть остаётся нетронутой, образуя привычную чёлку. При активном воздействии магии криокинеза его волосы светлеют до белоснежного оттенка, а глаза приобретают золотистый или холодно-голубой цвет. Последнее служит признаком истощения – синий оттенок глаз и ледяное дыхание указывают на приближение предела в использовании магических способностей, требуя перерыва."}),(0,i.jsx)(n.p,{children:"Рост Морана составляет около 186см при весе порядка 83кг. Телосложение атлетическое, сухое, без избыточной массы, являющееся результатом долгих лет тренировок. В то же время, невзирая на груду мышц, в его движениях нет резкости или суетливости: он двигается спокойно и точно, всегда осторожен, то ли экономя силы, то ли уверенный настолько, что его самоуверенности можно позавидовать."}),(0,i.jsx)(n.p,{children:"В одежде Моран придерживается закрытости и ухоженности, одевается в классические стили, отдавая предпочтение тёмным цветам, преимущественно чёрному. Обычно носит закрытый верх, рубашку с галстуком, зауженные брюки и прочную обувь, рассчитанную на длительные походы в случае необходимости резко сорваться по делу, и поверх обязательно плащ. Моран удивительно педантичен в вопросах чистоты и порядка, особенно когда речь идёт о нём самом, потому в нём нет никакой неаккуратности. Если вдруг осталось заметно пятно крови – он только вышел из гущи сражения, но уже поспешит убрать его, даже если оно послужит прекрасным элементом устрашения. На самих руках он носит чёрные перчатки, скрывающие метки Сталкера, особенно выраженные на правой руке – они могут причинять боль, поэтому из практичности Моран предпочитает не демонстрировать их окружающим и терпеть в случае, если боль застала его в самый неподходящий момент. На поясе Моран носит не только ножны для холодного оружия, но и снаряжение, подобранное с расчётом на бой и выживание: крепления, подсумки и утилитарные элементы, всегда находящиеся под рукой."}),(0,i.jsx)(n.p,{children:"Моран не стремится демонстрировать оружие или подчёркивать свою опасность — его внешность работает иначе: она не пугает напрямую, но оставляет стойкое ощущение небезопасности, которое трудно объяснить словами. Рядом с Мораном в принципе трудно отделаться от мысли, что любое движение может оказаться началом действия, к которому он уже подготовлен…"})]}),(0,i.jsx)(h,{src:"/anketa-images/moran/moran-main.webp"})]}),(0,i.jsx)(r,{title:"Навыки и умения",children:(0,i.jsxs)(d,{children:[(0,i.jsx)(j,{title:"Имитация эмоций",children:(0,i.jsx)(n.p,{children:"Умение имитировать эмоции. Он умеет плакать! И не только. Слёзы текут по щекам, губы дрожат, голос срывается — идеальная имитация отчаяния. Но это не ложь — издевательство. Внутри — тишина. Он смеётся, когда надо рыдать, и хмурится на шутки, зная, что это бесит больше прямого удара."})}),(0,i.jsx)(j,{title:"Тактический аналитик",children:(0,i.jsx)(n.p,{children:"Способность мгновенно «читать» поле боя, предугадывая действия противника на 2–3 шага вперёд. Он замечает дрожь в руке, дергающийся глаз, смещение центра тяжести — и знает, что последует за этим. Умеет превращать окружение в оружие: рычаг из обломка меча, ловушку из веток, баррикаду из трупов."})}),(0,i.jsx)(j,{title:"Психологические дуэли",children:(0,i.jsx)(n.p,{children:"Владеет искусством тихого прессинга: молчание, взгляд, едва заметная улыбка — и противник начинает оговариваться, раскрывая секреты. Специализируется на обратном допросе: задаёт вопросы, которые звучат как комплименты, а ответы на них — как признания."})}),(0,i.jsx)(j,{title:"Токсикология",children:(0,i.jsx)(n.p,{children:"Знает свойства сотни растений, грибов и желез животных, способных убить, парализовать или вызвать галлюцинации. Умеет приготовить яд, который сработает через час, день или даже месяц, подстраиваясь под привычки жертвы (например, добавляет токсин в табак или духи)."})}),(0,i.jsx)(j,{title:"Знание бестиария",children:(0,i.jsx)(n.p,{children:"Хорошо разбирается в поведенческих чертах многих существ бестиария и пустых благодаря частому сражению с ними."})}),(0,i.jsx)(j,{title:"Полевая медицина",children:(0,i.jsx)(n.p,{children:"Может остановить кровотечение, вправить вывих или даже провести ампутацию в полевых условиях."})}),(0,i.jsx)(j,{title:"Навык допроса",children:(0,i.jsx)(n.p,{children:"Знает, как причинить максимальную боль, не повредив жизненно важные органы — навык, отточенный за годы «бесед» с пленными."})}),(0,i.jsx)(j,{title:"Каллиграфия",children:(0,i.jsx)(n.p,{children:"Пишет изысканным почерком, который гипнотизирует своей геометрической точностью."})}),(0,i.jsx)(j,{title:"Дешифровка",children:(0,i.jsx)(n.p,{children:"Умеет расшифровывать немало шифров за счёт понимания паттернов."})}),(0,i.jsx)(j,{title:"Змеиный язык",children:(0,i.jsx)(n.p,{children:"Отлично понимает змеиный язык и умеет на нём разговаривать."})}),(0,i.jsx)(j,{title:"Фехтование",children:(0,i.jsx)(n.p,{children:"Опытный фехтовальщик. Очень опытный, не грех назвать профессионалом. Научился многим школам фехтования (как старым, так и новым), продолжая совершенствоваться прямо в боевых условиях. Умеет пользоваться охотничьим холодным оружием, мечами (шпагой, рапирой, саблей, катаной), копьём. По итогу отдал предпочтение полутораручному мечу. Также хорошо метает ножи."})}),(0,i.jsx)(j,{title:"Ориентирование на местности",children:(0,i.jsx)(n.p,{children:"Отлично ориентируется на местности."})}),(0,i.jsx)(j,{title:"Скрытность",children:(0,i.jsx)(n.p,{children:"Пусть и не имеет специальных магических способностей, однако умеет выслеживать, выжидать жертву, подкрадываться и расставлять ловушки (преимущ. самодельные)."})}),(0,i.jsx)(j,{title:"Языки",children:(0,i.jsx)(n.p,{children:"В совершенстве владеет немецким, английским и французским. Последние два выучил уже непосредственно в Энкраже."})}),(0,i.jsx)(j,{title:"Феноменальная память",children:(0,i.jsx)(n.p,{children:"Хорошая память, отлично запоминает лица и названия. Запах пота жертвы, дрожь в голосе при лжи, узор родинки на шее — всё это складывается в досье, которое он ведёт в уме. Однажды встретив человека, он может описать, какие пуговицы были на его камзоле десять лет назад."})}),(0,i.jsx)(j,{title:"Сверхчеловеческая реакция",children:(0,i.jsx)(n.p,{children:"Высокая скорость реакции, если быть точнее, то сверхчеловеческая. Обусловлено и при жизни, и уже, конечно же, с возрастом и опытом самой химеры в силу различных тренировок и некоторых дополнительных особенностей."})}),(0,i.jsx)(j,{title:"Физическая подготовка",children:(0,i.jsx)(n.p,{children:"Хорошая ловкость, титаническая выносливость."})}),(0,i.jsx)(j,{title:"Азартные игры",children:(0,i.jsx)(n.p,{children:"Обожает азартные игры. Его покерное лицо — эталон. Он может знать, что у соперника туз в рукаве, потому что тот почесал мочку уха ровно три раза. Ставит всё на кон не ради денег — ради момента, когда чья-то рука дрогнет, открывая слабость. Проигрывает редко, но если это происходит — улыбается."})}),(0,i.jsx)(j,{title:"Воровство",children:(0,i.jsx)(n.p,{children:"Отличный вор. Кошелёк исчезает из кармана, словно его никогда не было. Документы подменяются подделками, пока жертва пьёт вино."})})]})}),(0,i.jsx)(r,{title:"Слабости",children:(0,i.jsxs)(d,{children:[(0,i.jsx)(j,{title:"Длительное восстановление энергии",children:(0,i.jsx)(n.p,{children:"Длительное восстановление энергии. (200%)."})}),(0,i.jsx)(j,{title:"Двухъярусное ядро",children:(0,i.jsx)(n.p,{children:"Двухъярусное ядро. После того, как Каин искупил свои грехи, ядро Морана поглотило второе ядро и усилило свой потенциал, укрепив цепи. Кроме того, ЭПФО Каина тоже было поглощено, из-за чего у Морана теперь пусть и один облик, однако он более усилен, нежели был до этого. Минусом становится то, что такое ядро требует больше энергии, нежели обычное."})}),(0,i.jsx)(j,{title:"Перегрузка магических цепей",children:(0,i.jsx)(n.p,{children:"Возможная перегрузка магических цепей. Влечёт к потери способностей, а в случае Морана может и вовсе привести к смерти."})}),(0,i.jsx)(j,{title:"Изобилие энергии",children:(0,i.jsx)(n.p,{children:"Изобилие энергии. Привлекает нездоровое внимание тех, кто любит энергию."})}),(0,i.jsx)(j,{title:"Использование полного потенциала души",children:(0,i.jsx)(n.p,{children:"Используется полный потенциал души. Для поддержания более требовательного ядра одной душе становится несколько проблематичным, из-за чего Моран жертвует своей жизненной силой. Чем больше он использует свои способности, тем быстрее в нём угасает жизнь. Так, если он перегружается, следует быть аккуратным. Перегрузка видна как раз по белеющему цвету волос и голубым глазам. Критическая фаза начинается, когда он видит помутнения и у него идёт кровь из носа, тяжесть в теле, которая заставляет мгновенно склонить колено."})}),(0,i.jsx)(j,{title:"Уязвимость к огненной магии",children:(0,i.jsx)(n.p,{children:"Огненная магия. В силу того, что Моран немного может в криокинез, то есть сталкивается с использованием льда, в работу подключаются уже цепи Каина, а вот они как раз не переносят резких перепадов температур и слабы к огненным атакам. Посему и Моран перенимает эту слабость, но когда его волосы меняются на обратный чёрный цвет, эта слабость аннулируется. И так по кругу. Как только они появляются, Моран становится уязвим к огню."})}),(0,i.jsx)(j,{title:"Слуховые галлюцинации",children:(0,i.jsx)(n.p,{children:"Слуховые галлюцинации. Постоянно слышит какой-то женский голос, который его преследует. Это могут быть женские крики, плач, различные нашептывания. Как Моран предполагает, ему специально навиваются воспоминания, дабы он смягчился или поддался безумию. Однако в какой-то момент это способно очень сильно отвлечь Морана. А иногда и вовсе он начинает говорить сам с собой, но, как правило, делает это весьма редко."})}),(0,i.jsx)(j,{title:"Бессонница",children:(0,i.jsx)(n.p,{children:"Бессонница. В состоянии покоя Моран засыпает с очень большим трудом. Шанс заснуть у него составляет 3/10. Следовательно, он не способен восстанавливать энергию путём сна, из-за чего единственным выходом остаётся еда."})}),(0,i.jsx)(j,{title:"Слабость на дальних дистанциях",children:(0,i.jsx)(n.p,{children:"Слаб на дальних дистанциях. Может только защищаться или уклоняться. На крайний случай — отразить магическую атаку в полном или неполном %. По этой причине, если удастся держать Морана на дистанции, то можно обеспечить себе неплохое существование против него, ведя игру на истощение. Ну, а здесь уже надо быть предельно аккуратным тому, что решит так прижать Морана."})}),(0,i.jsx)(j,{title:"Слабость в рукопашном бою",children:(0,i.jsx)(n.p,{children:"Рукопашный бой. Несмотря на выносливость и скорость, без холодного оружия Моран может только избегать атак и наносить очень базовый урон. В то же время, с мечом/ножами он отлично умеет парировать и контратаковать удары, держать баланс. Поэтому главной целью противника в данном случае будет не ранить Морана и играть на истощение, а попытаться выбить у него оружие из рук."})}),(0,i.jsx)(j,{title:"Ледяное дыхание",children:(0,i.jsx)(n.p,{children:"Ледяное дыхание. Одна из слабостей, которая вызывается истощением магических сил Морана и является очень тревожным сигналом. При такой ситуации змей стремится избежать бой (если дыхание виднеется уже продолжительное время) любой ценой и скрыться."})})]})}),(0,i.jsx)(r,{title:"Связанные персонажи",children:(0,i.jsxs)(d,{children:[(0,i.jsx)(j,{title:"Каин О'Каннингем",children:(0,i.jsx)(n.p,{children:"Людской мир. Связаны крестовидной серьгой, которые оба носили в Энкраже."})}),(0,i.jsx)(j,{title:"Шумер (Герман фон Штраус)",children:(0,i.jsx)(n.p,{children:"Людской мир. Ныне известен как Герман фон Штраус. Когда-то давно Моран познакомился с одним человеком, что полностью изменил его образ жизни. После его смерти лишь одному единственному он умудрился дать клятву, предметом которого стал амулет."})})]})})]}),(0,i.jsx)(h,{src:"/anketa-images/moran/moran-main1.webp",size:"sm"}),(0,i.jsx)(p,{children:(0,i.jsx)(n.p,{children:"Земля проклята — и всё из-за нас. Тернии и волчцы произрастит она, нам, до коли не возвратимся в землю из которой вышли, ибо мы прах её"})})]})}function s(e,i){throw Error("Expected "+(i?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}e.s(["default",0,function(e={}){let{wrapper:s}={...(0,l.useMDXComponents)(),...e.components};return s?(0,i.jsx)(s,{...e,children:(0,i.jsx)(n,{...e})}):n(e)}])}]);